import{_ as a,c as i,o as t,a1 as e}from"./chunks/framework.7AAjiCkA.js";const u=JSON.parse('{"title":"V3 客户端介绍","description":"","frontmatter":{},"headers":[],"relativePath":"V3/V3 客户端功能.md","filePath":"V3/V3 客户端功能.md"}'),l={name:"V3/V3 客户端功能.md"},r=e('<h1 id="v3-客户端介绍" tabindex="-1">V3 客户端介绍 <a class="header-anchor" href="#v3-客户端介绍" aria-label="Permalink to &quot;V3 客户端介绍&quot;">​</a></h1><h2 id="新特性" tabindex="-1">新特性 <a class="header-anchor" href="#新特性" aria-label="Permalink to &quot;新特性&quot;">​</a></h2><ul><li>继承 V2 版本所有的功能</li><li>新的UI界面，更流程的使用体验</li></ul><p><img src="https://raw.gitmirror.com/krinlove99/pic/main/basetec/oichat.png" alt="1"></p><ul><li>工作空间：开放用户自定义模型、提示词的功能，基于X-Chat提供的模型之上，用户可以自行上传文档作为大模型知识库，打造用户专属模型。</li></ul><p><img src="https://raw.gitmirror.com/krinlove99/pic/main/basetec/modeldiy.jpg" alt="2"></p><ul><li>内置BASETEC X-搜索同款AI搜索引擎，AI生成+搜索，没有广告，直达结果</li></ul><p><img src="https://raw.gitmirror.com/krinlove99/pic/main/basetec/searxng.png" alt="3"></p><ul><li>大模型“记忆”：支持添加自己近期的动态，如正在学习金融/正在学习《易经》等，全站所有大模型将记住您的个人身份</li><li>支持与OpenAI相同的语音通话功能，实时对话交流</li><li>多达几十种个性化语音助手模型，详见X-Chat使用文档的《语音模型声线列表》介绍</li><li>支持多模型对话对比</li></ul><p><img src="https://raw.gitmirror.com/krinlove99/pic/main/basetec/e7427d560v15a8bf4522f90a99d5093a.jpg" alt="4"></p><ul><li>支持聊天记录随账号漫游，切换设备自动同步</li><li>支持隐私模式，本地浏览器及云端都将不保存您的对话信息</li><li>支持导入导出、归档及删除等多种对话管理功能</li><li>支持更多的界面个性化设置，如上传自定义背景图片等</li></ul><p><img src="https://raw.gitmirror.com/krinlove99/pic/main/basetec/xchat.jpg" alt="5"></p><h2 id="聊天记录同步及备份" tabindex="-1">聊天记录同步及备份 <a class="header-anchor" href="#聊天记录同步及备份" aria-label="Permalink to &quot;聊天记录同步及备份&quot;">​</a></h2><p>X-Chat V3 版本支持云同步，即在任何设备登录BASETEC账号后，都可以自动同步聊天记录，包括聊天记录、模型调校、使用习惯、文档资料等。同时，X-Chat V3 版本也支持聊天记录的本地备份，用户可以在设置中开启或关闭聊天记录的本地备份功能。</p><h2 id="查询账户信息" tabindex="-1">查询账户信息 <a class="header-anchor" href="#查询账户信息" aria-label="Permalink to &quot;查询账户信息&quot;">​</a></h2><p>普通用户可以在BASETEC 官网的个人中心中查看当前账户额度信息，包括：</p><ul><li>充值记录</li><li>剩余余额</li></ul><p>开发者、企业组织等商用用户需要前往API控制台中查看。</p><h2 id="充值" tabindex="-1">充值 <a class="header-anchor" href="#充值" aria-label="Permalink to &quot;充值&quot;">​</a></h2><p>购买额度：<a href="https://shop.basetec.top" target="_blank" rel="noreferrer">点此前往</a>。</p>',20),o=[r];function c(s,n,p,h,m,_){return t(),i("div",null,o)}const b=a(l,[["render",c]]);export{u as __pageData,b as default};
